h=w=20
g=[[0]*w for _ in range(h)]
# original rectangle
for r in range(2,9):
    for c in range(9,16): g[r][c]=2
# markers from test
marks=[(2,6),(3,19),(4,5),(7,1),(8,19),(12,9),(17,13),(19,15)]
for r,c in marks: g[r][c]=1
# Extend block rays to borders in each direction unless a marker lies on that row/column beyond the rectangle
# horizontal across block rows
for r in range(2,9):
    left_blocked=any(rr==r and c<9 for rr,c in marks)
    right_blocked=any(rr==r and c>15 for rr,c in marks)
    if not left_blocked:
        for c in range(9):
            if g[r][c]==0: g[r][c]=2
    if not right_blocked:
        for c in range(16,20):
            if g[r][c]==0: g[r][c]=2
# vertical above / below across block columns
for c in range(9,16):
    up_blocked=any(cc==c and r<2 for r,cc in marks)
    down_blocked=any(cc==c and r>8 for r,cc in marks)
    if not up_blocked:
        for r in range(2):
            if g[r][c]==0: g[r][c]=2
    if not down_blocked:
        for r in range(9,20):
            if g[r][c]==0: g[r][c]=2
print('\n'.join(' '.join(map(str,row)) for row in g))
